mapper.insert:
INSERT INTO admin_role (tenant_id, role_code, role_name, enabled)
VALUES (#{tenantId}, #{roleCode}, #{roleName}, #{enabled})
ON DUPLICATE KEY UPDATE role_name = #{roleName}, enabled = #{enabled}

mapper.delete:
DELETE rp FROM admin_role_permission rp
JOIN admin_role r ON r.id = rp.role_id
WHERE r.tenant_id = #{tenantId} AND r.role_code = #{roleCode}

mapper.insert:
INSERT INTO admin_role_permission (role_id, permission_id)
SELECT r.id, p.id FROM admin_role r JOIN admin_permission p
WHERE r.tenant_id = #{tenantId} AND r.role_code = #{roleCode}
  AND p.permission_code = #{permissionCode}
